    "tests": [
      {
        "id": "DRC_SUBLETTING_C01",
        "element_id": "DRC_SUBLETTING_E01",
        "text": "The relevant subletting, assignment, or parting with possession occurred on or after 9 June 1952.",
        "polarity": "POSITIVE",
        "source_refs": [
          {
            "source_id": "LAW:S02:DRC14:1b",
            "quote": "on or after the 9th day of June, 1952"
          }
        ],
        "source_status": "STATUTE",
        "interpretation_limits": [
          "The supplied materials do not state how the relevant date is proved or how continuing arrangements are dated."
        ]
      },
      {
        "id": "DRC_SUBLETTING_C02",
        "element_id": "DRC_SUBLETTING_E02",
        "text": "For subletting, a landlord-and-tenant relationship exists between tenant and sub-tenant and the incidents of letting or tenancy identified by the supplied opinion are present: transfer of an interest in the estate, payment of rent, and the right to possession as against the tenant in respect of the premises sublet.",
        "polarity": "POSITIVE",
        "source_refs": [
          {
            "source_id": "IK-190902:L110",
            "quote": "In subletting there exists the relationship of landlord and tenant as between the tenant and his sub-tenant and all the incidents of letting or tenancy have to be found, namely the transfer of an interest in the estate payment of rent, and the right to possession as against the tenant in respect of the Premises sublet."
          }
        ],
        "source_status": "COURT_ADOPTED",
        "interpretation_limits": [
          "No additional supplied rule explains how those incidents are proved or qualified."
        ]
      },
      {
        "id": "DRC_SUBLETTING_C03",
        "element_id": "DRC_SUBLETTING_E02",
        "text": "For assignment, the tenant divests himself of all rights that he has as a tenant.",
        "polarity": "POSITIVE",
        "source_refs": [
          {
            "source_id": "IK-190902:L110",
            "quote": "In assignment the tenant has to divest himself of all the rights that he has as a tenant."
          }
        ],
        "source_status": "COURT_ADOPTED",
        "interpretation_limits": [
          "The supplied law does not further define the mechanics, duration, or interaction of 'all the rights' with a disposition of part of the premises."
        ]
      },
      {
        "id": "DRC_SUBLETTING_C04",
        "element_id": "DRC_SUBLETTING_E02",
        "text": "For parting with possession, possession is vested by the tenant in another person by divesting the tenant of physical possession and the right to possession; divestment or abandonment of the right to possession is required.",
        "polarity": "POSITIVE",
        "source_refs": [
          {
            "source_id": "IK-190902:L111",
            "quote": "\"parting with possession\" must have been by the tenant."
          },
          {
            "source_id": "IK-190902:L112",
            "quote": "there must be vesting of possession by the tenant in another person by divesting himself not only of physical possession but also of the right to possession"
          },
          {
            "source_id": "IK-190902:L112",
            "quote": "The divestment or abandonment of the right to possession is necessary in order to invoke the clause of parting with possession"
          }
        ],
        "source_status": "COURT_ADOPTED",
        "interpretation_limits": [
          "In a license setting, the supplied opinion also states that the tenant is not said to part with possession unless the arrangement wholly ousts the tenant from legal possession of that part.",
          "The supplied law does not state whether that license formulation is exhaustive for every possible arrangement."
        ]
      },
      {
        "id": "DRC_SUBLETTING_C05",
        "element_id": "DRC_SUBLETTING_E04",
        "text": "The tenant did not obtain the landlord's consent in writing for the relevant disposition.",
        "polarity": "POSITIVE",
        "source_refs": [
          {
            "source_id": "LAW:S02:DRC14:1b",
            "quote": "without obtaining the consent in writing of the landlord;"
          }
        ],
        "source_status": "STATUTE",
        "interpretation_limits": [
          "The supplied materials do not allocate the burden concerning written consent or define its form, timing, scope, waiver, estoppel, or implied variants."
        ]
      },
      {
        "id": "DRC_SUBLETTING_C06",
        "element_id": "DRC_SUBLETTING_E02",
        "text": "For the parting-with-possession route, the tenant retains legal possession of the relevant part where there is concurrent user or mere use by others without wholly ousting the tenant from legal possession of that part.",
        "polarity": "NEGATIVE",
        "source_refs": [
          {
            "source_id": "IK-190902:L107",
            "quote": "If there is anything in the nature of a right to concurrent user there is no parting with possession"
          },
          {
            "source_id": "IK-190902:L112",
            "quote": "The mere user by other persons is no parting with Possession so long as the tenant retains the legal possession himself"
          },
          {
            "source_id": "IK-190902:L107",
            "quote": "A tenant cannot be said to part with the possession of any part of the premises unless his agreement with the license wholly ousts him from the legal possession of that part."
          }
        ],
        "source_status": "COURT_ADOPTED",
        "interpretation_limits": [
          "This is a defeating qualification only for the parting-with-possession route; the supplied material does not say it independently resolves subletting or assignment.",
          "The supplied material does not define every factual circumstance in which legal possession is retained."
        ]
      },
      {
        "id": "DRC_SUBLETTING_C07",
        "element_id": "DRC_SUBLETTING_E03",
        "text": "The relevant disposition concerns the whole or any part of the premises.",
        "polarity": "POSITIVE",
        "source_refs": [
          {
            "source_id": "LAW:S02:DRC14:1b",
            "quote": "the whole or any part of the premises"
          }
        ],
        "source_status": "STATUTE",
        "interpretation_limits": [
          "The supplied materials do not define how a relevant part of the premises is delineated or proved."
        ]
      }
